Can you audit auth on this orders controller before we ship it?

```typescript
// src/orders/orders.controller.ts
@Injectable()
export class OrdersController {
  constructor(private readonly db: PrismaService) {}

  // GET /orders/:orderId
  async getOrder(orderId: string, user: User) {
    return this.db.order.findUnique({ where: { id: orderId } });
  }

  // POST /orders/:orderId/cancel
  async cancelOrder(orderId: string, user: User) {
    const order = await this.db.order.findUnique({ where: { id: orderId } });
    if (!order || order.userId !== user.id) {
      throw new ForbiddenException();
    }
    return this.db.order.update({
      where: { id: orderId },
      data: { status: 'cancelled' },
    });
  }
}
```

We use JWTs for the API and server sessions for the web dashboard. Can you audit these two files for auth issues before launch?

```typescript
// src/auth/tokenService.ts
import jwt from 'jsonwebtoken';

export function verifyToken(token: string) {
  return jwt.verify(token, process.env.JWT_SECRET as string);
}

export function requireAuth(req, res, next) {
  try {
    const authHeader = req.headers.authorization ?? '';
    const token = authHeader.replace('Bearer ', '');
    req.user = verifyToken(token);
    next();
  } catch {
    res.status(401).json({ error: 'Unauthorized' });
  }
}
```

